// SPDX-License-Identifier: CC0-1.0
#include <atomic>
#include <chrono>
#include <cstdint>
#include <ctime>
struct BenchStamp { std::int64_t wall, cpu; };
inline BenchStamp bench_stamp() {
    std::atomic_signal_fence(std::memory_order_seq_cst);
    timespec t{};
    clock_gettime(CLOCK_THREAD_CPUTIME_ID, &t);
    const auto wall = std::chrono::steady_clock::now().time_since_epoch();
    return {std::chrono::duration_cast<std::chrono::nanoseconds>(wall).count(), static_cast<std::int64_t>(t.tv_sec) * 1000000000 + t.tv_nsec};
}
inline BenchStamp operator-(BenchStamp a, BenchStamp b) { return {a.wall-b.wall,a.cpu-b.cpu}; }

