#include HEADER
#include "bench_clock.hpp"
#include <algorithm>
#include <cstddef>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <memory>
#include <vector>
using Trie=BinaryTrie<std::uint32_t,29,67108864>;
struct Query { unsigned kind; std::uint32_t value; std::size_t rank; };
int main(int argc,char**argv){
    if(argc!=3)return 2;const auto n=static_cast<std::size_t>(std::strtoull(argv[1],nullptr,10));const int mode=std::atoi(argv[2]);
    const auto objects=n<=16?16:n<=1024?4:1;
    std::uint64_t random=72198912;auto next=[&]{random^=random<<13;random^=random>>7;random^=random<<17;return random;};
    std::vector<std::uint32_t>keys(n);for(auto&x:keys)x=static_cast<std::uint32_t>(next()&((1U<<30)-1));
    const std::size_t q=mode==8?(n<=1024?2048:131072):mode>=4?std::size_t{131072}:n;
    std::vector<Query>queries(q);std::vector<std::uint32_t>bag;bag.reserve(q);std::uint32_t lazy=0;
    for(std::size_t i=0;i<q;++i){
        if(mode==8){unsigned kind=static_cast<unsigned>(next()%10);if(bag.empty())kind=0;std::uint32_t x=static_cast<std::uint32_t>(next()&((1U<<30)-1));std::size_t rank=1;
            if(kind<4)bag.push_back(x^lazy);
            else if(kind<6){const auto at=next()%bag.size();x=bag[at]^lazy;bag[at]=bag.back();bag.pop_back();}
            else if(kind==8)rank=next()%bag.size()+1;
            else if(kind==9)lazy^=x;
            queries[i]={kind,x,rank};
        }else{const auto x=(n&&(i&3))?keys[next()%n]:static_cast<std::uint32_t>(next()&((1U<<30)-1));queries[i]={static_cast<unsigned>(mode),x,n?next()%n+1:1};}
    }
    const bool preload=mode>=2&&mode<=6;
    const auto construction_start=bench_stamp();
    std::vector<std::unique_ptr<Trie>>tries(objects);
    for(auto&t:tries){t=std::make_unique<Trie>();if(preload)for(std::size_t i=0;i<n;++i)t->add(keys[i],mode==3?static_cast<int>(i):-1);}
    const auto construction=bench_stamp()-construction_start;
    std::uint64_t checksum=0;std::size_t successful_deletes=0;
    const auto operation_start=bench_stamp();
    for(auto&t:tries){
        switch(mode){
        case 0:case 1:for(std::size_t i=0;i<n;++i)t->add(keys[i],mode==1?static_cast<int>(i):-1);break;
        case 2:case 3:for(std::size_t i=0;i<n;++i)successful_deletes+=t->del(keys[i],mode==3?static_cast<int>(i):-1);break;
        case 4:for(const auto&z:queries){checksum+=t->count(z.value);checksum+=t->contains(z.value);}break;
        case 5:if(n)for(const auto&z:queries){checksum+=t->count_less(z.value);checksum+=t->get_kth(static_cast<std::int64_t>(z.rank)).first;}break;
        case 6:if(n)for(std::size_t i=0;i<queries.size();++i){const auto&z=queries[i];if((i&63)==0)t->operate_xor(z.value);const auto a=t->min_xor(z.value),b=t->max_xor(z.value);checksum+=a.first;checksum+=b.first;checksum+=a.second.size();}break;
        case 7:for(std::size_t round=0;round<64;++round){for(std::size_t i=0;i<n;++i)t->add(static_cast<std::uint32_t>(i%16),static_cast<int>(i));for(std::size_t i=0;i<n;++i)successful_deletes+=t->del(static_cast<std::uint32_t>(i%16));}break;
        case 8:for(const auto&z:queries){if(z.kind<4)t->add(z.value);else if(z.kind<6)successful_deletes+=t->del(z.value);else if(z.kind==6)checksum+=t->count(z.value);else if(z.kind==7)checksum+=t->min_xor(z.value).first;else if(z.kind==8){checksum+=t->count_less(z.value);checksum+=t->get_kth(static_cast<std::int64_t>(z.rank)).first;}else t->operate_xor(z.value);}break;
        default:return 3;
        }
    }
    const auto operation=bench_stamp()-operation_start;
    std::uint64_t size_sum=0;
    for(auto&t:tries){size_sum+=t->size();if((mode==0||mode==1||preload&&mode!=2&&mode!=3)&&t->size()!=n)return 4;if((mode==2||mode==3||mode==7)&&!t->empty())return 5;}
    if((mode==2||mode==3)&&successful_deletes!=n*objects)return 6;if(mode==7&&successful_deletes!=n*64*objects)return 7;
    checksum+=successful_deletes;checksum+=size_sum;
    const auto destruction_start=bench_stamp();std::vector<std::unique_ptr<Trie>>().swap(tries);const auto destruction=bench_stamp()-destruction_start;
    const auto operations=objects*(mode==7?128*n:mode>=4?q:n);
    std::printf("%zu %zu %jd %jd %jd %jd %jd %jd %ju\n",static_cast<std::size_t>(objects),operations,static_cast<std::intmax_t>(construction.wall),static_cast<std::intmax_t>(construction.cpu),static_cast<std::intmax_t>(operation.wall),static_cast<std::intmax_t>(operation.cpu),static_cast<std::intmax_t>(destruction.wall),static_cast<std::intmax_t>(destruction.cpu),static_cast<std::uintmax_t>(checksum));
}

