// SPDX-License-Identifier: CC0-1.0
#include <cstddef>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <new>
#include <sys/resource.h>
namespace memory_observer {
struct alignas(std::max_align_t) Header { std::size_t size; };
std::size_t live = 0, peak = 0, allocations = 0, frees = 0, requested = 0;
}
void* operator new(std::size_t n) {
    using namespace memory_observer;
    auto* p = static_cast<Header*>(std::malloc(sizeof(Header) + (n ? n : 1)));
    if (!p) throw std::bad_alloc();
    p->size = n; live += n; if (live > peak) peak = live; ++allocations; requested += n;
    return p + 1;
}
void operator delete(void* p) noexcept {
    if (!p) return;
    using namespace memory_observer;
    auto* h = static_cast<Header*>(p) - 1; live -= h->size; ++frees; std::free(h);
}
void operator delete(void* p, std::size_t) noexcept { ::operator delete(p); }
void* operator new[](std::size_t n) { return ::operator new(n); }
void operator delete[](void* p) noexcept { ::operator delete(p); }
void operator delete[](void* p, std::size_t) noexcept { ::operator delete(p); }
#include HEADER
void emit(const char* phase, std::size_t cycle) {
    using namespace memory_observer;
    rusage usage{}; getrusage(RUSAGE_SELF,&usage);
    std::printf("%s %zu %zu %zu %zu %zu %zu %jd\n",phase,cycle,live,peak,allocations,frees,requested,static_cast<std::intmax_t>(usage.ru_maxrss));
}
int main(int argc,char**argv) {
    if(argc!=4)return 2;
    const int mode=std::atoi(argv[1]);const auto n=static_cast<std::size_t>(std::strtoull(argv[2],nullptr,10)),cycles=static_cast<std::size_t>(std::strtoull(argv[3],nullptr,10));
    emit("start",0);
#if NODE_MEMORY
    for(std::size_t cycle=1;cycle<=cycles;++cycle){auto h=make_chain(n);if(chain_size(h)!=n)return 3;clear_chain(h);if((cycle&(cycle-1))==0||cycle==cycles)emit("empty",cycle);}
#else
    using Trie=BinaryTrie<std::uint32_t,29,67108864>;
    if(mode==0){
        for(std::size_t cycle=1;cycle<=cycles;++cycle){{Trie t;for(std::size_t i=0;i<n;++i)t.add(static_cast<std::uint32_t>(i));}if((cycle&(cycle-1))==0||cycle==cycles)emit("after_destroy",cycle);}
    }else{
        {
            Trie t;emit("constructed",0);
            for(std::size_t cycle=1;cycle<=cycles;++cycle){for(std::size_t i=0;i<n;++i)t.add(static_cast<std::uint32_t>(i%16),static_cast<int>(i));for(std::size_t i=0;i<n;++i)if(!t.del(static_cast<std::uint32_t>(i%16)))return 4;if(!t.empty())return 5;if((cycle&(cycle-1))==0||cycle==cycles)emit("empty_reused",cycle);}
        }
        emit("after_destroy",cycles);
    }
#endif
    emit("end",cycles);
}

